91:+        word_delims = _T("");
92:+
93:+    while(off != end) {
94:+        if(scan_backwards)
95:+            off--;
96:+
97:+        /* Only accept extra and delimiter characters if they're not part of a
98:+         * resolved mark. */
99:+        if(!ISALNUM(off)  &&  !ISWHITESPACE(off)) {
100:+            if((!scan_backwards && md_scan_right_for_resolved_mark(ctx, *p_cursor, off, p_cursor) != NULL)  ||
101:+               (scan_backwards && md_scan_left_for_resolved_mark(ctx, *p_cursor, off, p_cursor) != NULL)) {
102:+                if(scan_backwards)
103:+                    off++;
104:+                break;
105:+            }
106:+        }
107:+
108:+        /* The autolink can be _inside_ brackets so we disallow unbalanced bracket pairs in the URL.
109:+         * (Note the brackets are not allowed in e-mail username, so we happily skip this in that case.) */
110:+        if(!scan_backwards) {
111:+            if(CH(off) == _T('(')) {
112:+                n_open_brackets++;
113:+            } else if(CH(off) == _T(')')) {
114:+                if(n_open_brackets <= 0)
115:+                    break;
116:+                n_open_brackets--;
117:+            }
118:+        }
119:+
120:+        if(ISALNUM(off)  ||  ISANYOF(off, word_extra)) {
121:+            seen_word_delim = FALSE;
122:+            seen_component_delim = FALSE;
123:+        } else {
124:+            if(seen_word_delim)
125:+                break;
126:+
127:+            if(ISANYOF(off, word_delims)) {
128:+                seen_word_delim = TRUE;
129:+            } else if(component_delim != _T('\0')  &&  CH(off) == component_delim) {
130:+                if(seen_component_delim)
131:+                    break;
132:+                seen_component_delim = TRUE;
133:+                component_beg = off;
134:+                n_components++;
135:+            } else {
136:+                if(scan_backwards)
137:+                    off++;
138:+                break;
139:+            }
140:+        }
141:+
142:+        if(!scan_backwards)
143:+            off++;
144:+    }
145:+
146:+    /* Rollback falsely consumed delimiter. */
147:+    if(seen_word_delim || seen_component_delim)
148:+        off = (scan_backwards ? off+1 : off-1);
149:+
150:+    if(off != component_beg)
151:+        n_components++;
152:+
153:+    if(n_open_brackets != 0)
154:+        return -1;
155:+
156:+    *p_end = off;
157:+    return n_components;
